      "statement": "INSERT INTO notes (owner_id, title, created_at) VALUES (?, ?, ?)",
      "bindings": [
        {
          "source": "actor",
          "field": "id"
        },
        {
          "source": "input",
          "key": "title",
          "type": "string",
          "maxLength": 500
        },
        {
          "source": "kernel",
          "field": "now"
        }
      ]
    },
    "notes.delete": {
      "kind": "mutation",
      "access": "authenticated",
      "statement": "DELETE FROM notes WHERE id = ? AND owner_id = ?",
      "bindings": [
        {
          "source": "input",
