{
  "version": 1,
  "actions": {
    "me.join": {
      "kind": "mutation",
      "access": "authenticated",
      "statement": "INSERT INTO profiles (user_id, display_name, role, joined_at) VALUES (?1, ?2, CASE WHEN ?3 = 'owner' THEN 'owner' ELSE 'member' END, ?4) ON CONFLICT (user_id) DO NOTHING",
      "bindings": [
        {
          "source": "actor",
          "field": "id"
        },
        {
          "source": "input",
          "key": "displayName",
          "type": "string",
          "maxLength": 40
        },
        {
          "source": "actor",
          "field": "role"
        },
        {
          "source": "kernel",
          "field": "now"
        }
      ]
    },
    "me.get": {
      "kind": "query",
      "access": "authenticated",
      "statement": "SELECT user_id, display_name, role FROM profiles WHERE user_id = ?1 LIMIT 1",
      "bindings": [
        {
          "source": "actor",
          "field": "id"
        }
      ]
    },
    "posts.list": {
      "kind": "query",
      "access": "authenticated",
      "statement": "SELECT p.id, p.body, p.created_at, p.author_id, a.display_name AS author FROM posts p LEFT JOIN profiles a ON a.user_id = p.author_id ORDER BY p.id DESC LIMIT 50",
      "bindings": []
    },
    "posts.add": {
      "kind": "mutation",
      "access": "authenticated",
      "statement": "INSERT INTO posts (author_id, body, created_at) VALUES (?1, ?2, ?3)",
      "bindings": [
        {
          "source": "actor",
          "field": "id"
        },
        {
          "source": "input",
          "key": "body",
          "type": "string",
          "maxLength": 2000
        },
        {
          "source": "kernel",
          "field": "now"
        }
      ]
    },
    "posts.remove": {
      "kind": "mutation",
      "access": "authenticated",
      "guard": "Only its author or an admin can remove a post.",
      "statement": "DELETE FROM posts WHERE id = ?2 AND (author_id = ?1 OR (SELECT role FROM profiles WHERE user_id = ?1) IN ('admin', 'owner'))",
      "bindings": [
        {
          "source": "actor",
          "field": "id"
        },
        {
          "source": "input",
          "key": "id",
          "type": "number"
        }
      ]
    },
    "members.list": {
      "kind": "query",
      "access": "authenticated",
      "statement": "SELECT user_id, display_name, role, joined_at FROM profiles WHERE (SELECT role FROM profiles WHERE user_id = ?1) IN ('admin', 'owner') ORDER BY display_name LIMIT 100",
      "bindings": [
        {
          "source": "actor",
          "field": "id"
        }
      ]
    },
    "members.promote": {
      "kind": "mutation",
      "access": "authenticated",
      "guard": "Only the owner can make a member an admin.",
      "statement": "UPDATE profiles SET role = 'admin' WHERE user_id = ?1 AND role = 'member' AND ?2 = 'owner'",
      "bindings": [
        {
          "source": "input",
          "key": "userId",
          "type": "string",
          "maxLength": 64
        },
        {
          "source": "actor",
          "field": "role"
        }
      ]
    },
    "members.demote": {
      "kind": "mutation",
      "access": "authenticated",
      "guard": "Only the owner can return an admin to member.",
      "statement": "UPDATE profiles SET role = 'member' WHERE user_id = ?1 AND role = 'admin' AND ?2 = 'owner'",
      "bindings": [
        {
          "source": "input",
          "key": "userId",
          "type": "string",
          "maxLength": 64
        },
        {
          "source": "actor",
          "field": "role"
        }
      ]
    }
  }
}

