files.actions.json:
{
  "version": 1,
  "actions": {
    "github.receive": {
      "kind": "mutation",
      "access": "anonymous",
      "http": {
        "method": "POST",
        "path": "/hooks/github",
        "signature": {
          "provider": "github",
          "secret": "github_webhook"
        },
        "fields": {
          "id": "$.issue.node_id",
          "title": "$.issue.title",
          "repo": "$.repository.full_name"
        }
      },
      "statement": "INSERT INTO events (external_id, title, repo, received_at) VALUES (?1, ?2, COALESCE(?3, ''), ?4) ON CONFLICT (external_id) DO NOTHING",
      "bindings": [
        {
          "source": "input",
          "key": "id",
          "type": "string",
          "maxLength": 100
        },
        {
          "source": "input",
          "key": "title",
          "type": "string",
          "maxLength": 200
        },
        {
          "source": "input",
          "key": "repo",
          "type": "string",
          "maxLength": 200,
          "nullable": true
        },
        {
          "source": "kernel",
          "field": "now"
        }
      ]
    },
    "events.list": {
      "kind": "query",
      "access": "authenticated",
      "statement": "SELECT id, external_id, title, repo, received_at FROM events WHERE ?1 = 'owner' ORDER BY id DESC LIMIT 100",
      "bindings": [
        {
          "source": "actor",
          "field": "role"
        }
      ]
    }
  }
}

files.app.js:
const $ = (selector) => document.querySelector(selector);
const statusLine = $('#status');

function escapeHtml(value) {
  const node = document.createElement('span');
  node.textContent = value ?? '';
  return node.innerHTML;
}

function when(ms) {
  return new Date(ms).toLocaleString();
}

function say(message, tone) {
  statusLine.textContent = message;
  if (tone) statusLine.dataset.tone = tone;
  else delete statusLine.dataset.tone;
}

function showError(error) {
  say(error instanceof Error ? error.message : String(error), 'danger');
}

async function start() {
  const session = await miniapp.auth.session();
  $('#identity').textContent = session.role === 'anonymous' ? '' : session.name;
  $('#sign-in').hidden = session.role !== 'anonymous';
  $('#feed').hidden = session.role !== 'owner';
  if (session.role !== 'owner') return;
  const events = await miniapp.actions.call('events.list');
  $('#events').innerHTML = events.length ? events.map(event =>
    '<article class="ui-list-item"><div class="ui-list-main"><p>' + escapeHtml(event.title) + '</p><small>' + escapeHtml(event.repo || 'GitHub') + ' · ' + when(event.received_at) + '</small></div></article>'
  ).join('') : '<p class="ui-list-empty">No events yet. They arrive once the webhook is set up.</p>';
}

$('#sign-in').addEventListener('click', async () => { await miniapp.auth.signIn(); await start(); });

try { await start(); } catch (error) { showError(error); }

files.schema.sql:
-- Written only by the signed route. A redelivery of the same event changes nothing.
CREATE TABLE IF NOT EXISTS events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  external_id TEXT NOT NULL,
  title TEXT NOT NULL,
  repo TEXT NOT NULL DEFAULT '',
  received_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS events_external_id_unique ON events(external_id);

