  --ds-warning-soft: #fff5e5;
  --ds-danger: #9f1239;
  --ds-danger-soft: #fde8ec;
  --ds-radius-sm: 0;
  --ds-radius: 0;
  --ds-radius-lg: 0;
  --ds-space-1: 4px;
  --ds-space-2: 8px;
  --ds-space-3: 12px;
  --ds-space-4: 16px;
  --ds-space-6: 24px;
  --ds-space-8: 32px;
  /* Offset shadows without blur; muted ink so one surface can stay quiet */
  --ds-shadow-sm: 2px 2px 0 #c5c1b5;
