      --ds-ink: #0d0e0b;
      --ds-stroke: #6b7182;
      --ds-field: #12141a;
      --ds-info: #8db4f5;
      --ds-info-soft: #1d2a42;
      --ds-s1: #3987e5;
      --ds-s2: #d95926;
      --ds-s3: #199e70;
      --ds-s4: #c98500;
      --ds-s5: #d55181;
      --ds-text: #eceef4;
      --ds-muted: #a4abba;
      --ds-accent: #c8f34a;
      --ds-accent-hover: #d4f85a;
      --ds-accent-soft: #3a4220;
      --ds-success: #8fc32f;
      --ds-success-soft: #2a3318;
      --ds-warning: #e2b56a;
      --ds-warning-soft: #3a2e16;
      --ds-danger: #ff9aae;
