.ui-button {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 7px;
  min-width: 0;
  min-height: 36px;
  padding: 0 13px;
  border: var(--ds-bw) solid var(--ds-stroke);
  border-radius: var(--ds-radius);
  background: var(--ds-surface);
  color: var(--ds-text);
  font: 750 12px/1.3 var(--ds-font);
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  box-shadow: var(--ds-shadow);
  transition: background 120ms ease, color 120ms ease, translate 80ms ease, box-shadow 80ms ease;
}
.ui-button:not(.ui-button-primary):not(.ui-button-ghost):not(.ui-button-danger):hover:not(:disabled) {
  background: var(--ds-text);
  color: var(--ds-surface);
  box-shadow: none;
}
.ui-button:active:not(:disabled) { translate: var(--ds-press) var(--ds-press); box-shadow: none; }
.ui-button-primary {
  border-color: var(--ds-stroke);
  background: var(--ds-accent);
  color: var(--ds-on-accent);
}
.ui-button-primary:hover:not(:disabled) { background: var(--ds-accent-hover); color: var(--ds-on-accent); box-shadow: var(--ds-shadow-sm); }
