}
.ui-input::placeholder, .ui-textarea::placeholder { color: var(--ds-muted); }
.ui-input:disabled { background: var(--ds-subtle); color: var(--ds-muted); }
.ui-input[aria-invalid="true"] { border-color: var(--ds-danger); }
.ui-field { display: grid; gap: 7px; align-content: start; font: 600 12px/1.5 var(--ds-font); }
.ui-field small { color: var(--ds-muted); font-size: 11px; font-weight: 400; font-family: var(--ds-mono); }
.ui-field:has([aria-invalid="true"]) small { color: var(--ds-danger); }
.ui-badge {
