.ui-table-scroll { overflow-x: auto; }
.ui-table { width: 100%; border-collapse: collapse; font: 400 14px/1.5 var(--ds-font); color: var(--ds-text); }
.ui-table caption { text-align: left; font-size: 12px; color: var(--ds-muted); margin-bottom: 12px; }
.ui-table th, .ui-table td { padding: 12px; border-bottom: 1px solid var(--ds-border); text-align: left; vertical-align: top; overflow-wrap: anywhere; }
.ui-table thead th { border-top: var(--ds-bw) solid var(--ds-line); border-bottom: var(--ds-bw) solid var(--ds-line); font: 500 11px/1.4 var(--ds-mono); text-transform: var(--ds-label-case); letter-spacing: .06em; color: var(--ds-muted); }
.ui-table th:first-child, .ui-table td:first-child { padding-left: 0; }
.ui-table th[scope="row"] { font-weight: 650; min-width: 140px; color: var(--ds-text); }
.ui-table td { font-variant-numeric: tabular-nums; }
